package sdk_test
import("context";"testing";"github.com/modelcontextprotocol/go-sdk/mcp")
func TestPinnedSDKHandshakeAndToolDiscovery(t *testing.T){ctx:=context.Background();s:=mcp.NewServer(&mcp.Implementation{Name:"m0-fixture",Version:"1"},nil);mcp.AddTool(s,&mcp.Tool{Name:"echo"},func(ctx context.Context,req *mcp.CallToolRequest,in struct{})(*mcp.CallToolResult,struct{},error){return &mcp.CallToolResult{},struct{}{},nil});c:=mcp.NewClient(&mcp.Implementation{Name:"m0-client",Version:"1"},nil);st,ct:=mcp.NewInMemoryTransports();ss,err:=s.Connect(ctx,st,nil);if err!=nil{t.Fatal(err)};defer ss.Close();cs,err:=c.Connect(ctx,ct,nil);if err!=nil{t.Fatal(err)};defer cs.Close();tools,err:=cs.ListTools(ctx,nil);if err!=nil||len(tools.Tools)!=1{t.Fatal("expected controlled tool discovery",err)}}
